"use strict";
/* practice.js - Practice Mode.  NOTHING is hard-coded here: every exercise is generated by the backend (the AI, or the backend's verified offline bank),
   and every answer is checked by the backend, which runs the player's code in its own safe interpreter.  The browser only shows the task,
   sends the player's code, and displays the server's verdict.  If the backend cannot be reached the mode says so (it never invents exercises). */
const PRACTICE_LABEL={syntax:'SYNTAX ERROR',logic:'LOGIC ERROR',runtime:'RUNTIME ERROR',output:'OUTPUT ERROR',unsupported:'NOT SUPPORTED YET',missing:'MISSING FUNCTION'};
const Practice={timeoutMs:30000,
 base(){return(GHOST_CONFIG.apiBase||'').replace(/\/+$/,'')},
 async api(path,body){const ac=new AbortController(),t=setTimeout(()=>ac.abort(),this.timeoutMs);
  try{const r=await fetch(this.base()+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ac.signal});let d=null;try{d=await r.json()}catch(e){}
   if(!r.ok){const e=new Error((d&&d.message)||'HTTP '+r.status);e.code=d&&d.error;throw e}return d}
  catch(e){if(e.name==='AbortError'){const x=new Error('The AI took too long to answer.');x.code='timeout';throw x}throw e}finally{clearTimeout(t)}},
 open(){if(state!=='menu')return;prev='menu';state='chal';cur={pr:true,done:false,fails:0,busy:false,train:true,q:null};$('cclose').style.display='';$('cnext').disabled=false;show('chal');this.load()},
 async load(){const c=cur;if(!c)return;c.busy=true;c.q=null;c.done=false;c.fails=0;
  $('ct').textContent='PRACTICE MODE';$('cm').textContent='';$('cl').textContent='';$('cc').style.display='none';$('cb').textContent='Generating your next exercise...';$('cguide').textContent='';$('cfb').textContent='';$('cin').value='';$('cin').disabled=true;$('csub').disabled=true;$('cclose').textContent='BACK';
  if(!this.base())return this.fail(c,'Practice Mode needs the online AI service, and this copy of the game is not connected to one. Set your backend address in js/config.js (see backend/README.md). Training your Python skills still works through the in-game challenges.');
  try{const d=await this.api('/api/questions/generate',{level:clamp(+SAVE.lvl||1,1,10),mode:'practice',recent:SAVE.prac.recent});if(cur!==c)return;c.q=d.question;c.note=d.note;this.render(c)}
  catch(e){if(cur===c)this.fail(c,'The AI is temporarily unavailable ('+e.message+'). Press NEXT QUEST to try again, or BACK to return to the menu.')}},
 fail(c,t){c.busy=false;$('cb').textContent=t},
 render(c){const q=c.q,code=q.kind==='code';c.busy=false;
  $('ct').textContent='PRACTICE: '+String(q.topic).toUpperCase();$('cm').textContent='DIFFICULTY '+q.difficulty+'/5  |  '+(q.source==='ai'?'AI-GENERATED':'OFFLINE QUESTION BANK (AI UNAVAILABLE)')+'  |  SOLVED '+SAVE.prac.ok;
  $('cl').textContent=code?'Write real Python. The function must be named '+q.fn+'('+q.params.join(', ')+'). Use return to give the result back (do not print it).':q.kind==='expr'?'No coding needed here: work out the value and type it.':'Type your answer in the box.';
  $('cb').textContent=q.question+(code&&q.examples.length?'\n\nFor example:\n'+q.examples.map(e=>'  '+e.call+'  ->  '+e.expected).join('\n')+(q.hidden_tests?'\n('+q.hidden_tests+' more hidden tests also run)':''):'');
  $('cin').disabled=false;$('cin').value=code?q.starter:'';$('csub').disabled=false;$('cfb').textContent=c.note||'';
  $('cguide').textContent=SAVE.prac.n<2?(code?'How to: 1) read the whole task  2) type your function in the green box (4 spaces per indent)  3) press RUN CHECK. Stuck? Press HINT.':'Type your answer in the green box and press RUN CHECK. Stuck? Press HINT.'):'';
  Voice.event('lesson');if(!(window.matchMedia&&matchMedia('(pointer:coarse)').matches))$('cin').focus()},
 record(q,ok){const s=SAVE.prac;s.recent.push({difficulty:q.difficulty,correct:ok,topic:q.topic,q:q.question});s.recent=s.recent.slice(-10);s.n++;if(ok)s.ok++;store()},
 async check(){const c=cur;if(!c||c.busy||!c.q||c.done)return;const code=$('cin').value;if(!code.trim()){$('cfb').textContent='Type your answer first.';return}
  c.busy=true;$('csub').disabled=true;$('cfb').textContent='Checking with the server...';
  try{const r=await this.api('/api/questions/evaluate',{id:c.q.id,answer:code});if(cur===c)this.result(c,r)}
  catch(e){if(cur===c)$('cfb').textContent=e.code==='unknown_question'?'That exercise expired. Press NEXT QUEST for a new one.':'The AI service is temporarily unavailable ('+e.message+'). Your answer was not marked wrong. Try again.'}
  finally{if(cur===c){c.busy=false;if(!c.done)$('csub').disabled=false}}},
 result(c,r){const q=c.q,rows=(r.tests||[]).map(t=>(t.passed?'PASS  ':'FAIL  ')+t.call+'  ->  '+t.got+(t.passed?'':'   (expected '+t.expected+')')).join('\n'),hid=r.hidden&&r.hidden.total?'\nHidden tests: '+r.hidden.passed+' of '+r.hidden.total+' passed':'';
  if(r.correct){c.done=true;sfx('ok');Voice.event('solved');this.record(q,true);const first=SAVE.pr.length<19&&!SAVE.pr.includes(q.id);if(first){SAVE.pr.push(q.id);SAVE.credits+=20}store();$('csub').disabled=true;$('cclose').textContent='CONTINUE';
   $('cfb').textContent='PASSED. '+(r.feedback||'')+' '+(r.explanation||'')+(first?' +20 credits.':'')+(rows?'\n\n'+rows:'')+'\n\nPress NEXT QUEST for the next exercise.';return}
  sfx('no');c.fails++;Voice.event('wrong');
  let m=(r.kind==='indent'||!PRACTICE_LABEL[r.kind]?'':PRACTICE_LABEL[r.kind]+': ')+(r.feedback||'Not quite.')+(r.line&&r.kind==='runtime'?' (line '+r.line+')':'')+(rows?'\n\n'+rows+hid:'');
  if(r.finished){c.done=true;this.record(q,false);$('csub').disabled=true;$('cclose').textContent='CONTINUE';m+='\n\nExplanation: '+(r.explanation||'')+(r.solution?'\n\nSOLUTION (study it, then try the next one):\n'+r.solution:'')}
  else if(c.fails>=3)m+='\n\nHint: '+q.hint;
  $('cfb').textContent=m},
 hint(){if(cur&&cur.q)$('cfb').textContent='HINT: '+cur.q.hint},
 next(){const c=cur;if(!c||!c.pr||c.busy)return;this.load()}};
$('practb').onclick=()=>Practice.open();
